/**
 * Ticket #20 acceptance test — the contract for asset kinds, attachments and text-layout rooms.
 * Do not edit this file to make it pass.
 */
import { describe, expect, it } from 'vitest';
import {
  ASSET_KINDS,
  fitCells,
  fitColumnsToCells,
  frameBob,
  kindDefaults,
  parseSpec,
  sliceTiles,
  spriteFrameMeta,
  type AssetKind,
} from '../../scripts/lib/gemini-art';
import { buildRoomTmx, buildTsx, type RoomLayoutSpec } from '../../scripts/lib/room-layout';
import { placeAttachment, validateAttachments } from '../../assets/scripts/core/art/attachments';
import { parseTmxLevel } from '../../assets/scripts/core/level/tmx';
import type { PngImage } from '../../scripts/lib/png';

type Pixel = readonly [number, number, number, number];
const CLEAR: Pixel = [0, 0, 0, 0];
const RED: Pixel = [200, 0, 0, 255];
const BLUE: Pixel = [0, 0, 200, 255];
const GREEN: Pixel = [0, 200, 0, 255];

function canvas(width: number, height: number, fill: Pixel = CLEAR): PngImage {
  const data = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i += 1) data.set(fill, i * 4);
  return { width, height, data };
}

function rect(image: PngImage, x0: number, y0: number, w: number, h: number, p: Pixel): void {
  for (let y = y0; y < y0 + h; y += 1) for (let x = x0; x < x0 + w; x += 1) image.data.set(p, (y * image.width + x) * 4);
}

function pixel(image: PngImage, x: number, y: number): number[] {
  return Array.from(image.data.subarray((y * image.width + x) * 4, (y * image.width + x) * 4 + 4));
}

/** Opaque bbox of one frame of an output sheet, in frame-local coordinates. */
function frameBox(image: PngImage, fx: number, fy: number, fw: number, fh: number): { x0: number; y0: number; x1: number; y1: number } | null {
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -1;
  let y1 = -1;
  for (let y = 0; y < fh; y += 1) {
    for (let x = 0; x < fw; x += 1) {
      if ((image.data[((fy * fh + y) * image.width + fx * fw + x) * 4 + 3] ?? 0) < 128) continue;
      x0 = Math.min(x0, x);
      y0 = Math.min(y0, y);
      x1 = Math.max(x1, x);
      y1 = Math.max(y1, y);
    }
  }
  return x1 < 0 ? null : { x0, y0, x1, y1 };
}

const ANIMATED = { frameWidth: 16, frameHeight: 16, fps: 8, loop: true };
function specFor(kind: AssetKind): Record<string, unknown> {
  const base = { kind, key: `thing.${kind}`, source: 'art-source/gemini/x.png', sheet: `generated/x/${kind}.png` };
  switch (kind) {
    case 'character':
    case 'monster':
      return { ...base, ...ANIMATED, layout: 'grid', directions: ['down', 'up', 'left', 'right'], frames: 4, anchor: 'feet' };
    case 'attachment':
      return { ...base, frameWidth: 16, frameHeight: 16, layout: 'grid', directions: ['down', 'up', 'left', 'right'], frames: 1 };
    case 'boss':
    case 'prop':
      return { ...base, ...ANIMATED, layout: 'strip', directions: [], frames: 4, anchor: 'feet' };
    case 'vfx':
    case 'particle':
      return { ...base, ...ANIMATED, loop: false, layout: 'strip', directions: [], frames: 6 };
    case 'icon':
      return { ...base, sheet: 'generated/icons/skills', frameWidth: 16, frameHeight: 16, names: ['swords', 'shield'], columns: 2 };
    case 'ui':
      return { ...base, frameWidth: 48, frameHeight: 32, nineSlice: { left: 4, right: 5, top: 6, bottom: 7 } };
    case 'tileset':
      return { ...base, frameWidth: 16, frameHeight: 16, columns: 4, rows: 3 };
  }
}

describe('#20 asset kinds in the spec', () => {
  it('lists the ten kinds', () => {
    expect([...ASSET_KINDS].sort()).toEqual(
      ['attachment', 'boss', 'character', 'icon', 'monster', 'particle', 'prop', 'tileset', 'ui', 'vfx'],
    );
  });

  it('accepts every kind with only the fields that kind needs', () => {
    for (const kind of ASSET_KINDS) {
      const asset = parseSpec({ assets: [specFor(kind)] }).assets[0];
      expect(asset?.kind, kind).toBe(kind);
    }
  });

  it('keeps icon names, the source grid and nine-slice insets', () => {
    const icon = parseSpec({ assets: [specFor('icon')] }).assets[0];
    expect(icon?.names).toEqual(['swords', 'shield']);
    expect(icon?.columns).toBe(2);
    const ui = parseSpec({ assets: [specFor('ui')] }).assets[0];
    expect(ui?.nineSlice).toEqual({ left: 4, right: 5, top: 6, bottom: 7 });
    const tileset = parseSpec({ assets: [specFor('tileset')] }).assets[0];
    expect([tileset?.columns, tileset?.rows]).toEqual([4, 3]);
  });

  it('rejects an unknown kind', () => {
    expect(() => parseSpec({ assets: [{ ...specFor('monster'), kind: 'dragon' }] })).toThrow(/kind/);
  });

  it('still reads the old role field', () => {
    const legacy: Record<string, unknown> = { ...specFor('monster') };
    delete legacy['kind'];
    expect(parseSpec({ assets: [{ ...legacy, role: 'monster' }] }).assets[0]?.kind).toBe('monster');
    expect(parseSpec({ assets: [{ ...legacy, role: 'actor' }] }).assets[0]?.kind).toBe('character');
    expect(parseSpec({ assets: [{ ...legacy, role: 'boss' }] }).assets[0]?.kind).toBe('boss');
  });
});

describe('#20 kind defaults', () => {
  it('centres effects, icons and attachments; stands bodies on their feet', () => {
    for (const kind of ['vfx', 'particle', 'icon', 'attachment'] as const) {
      expect(kindDefaults(kind), kind).toMatchObject({ fit: 'center', anchor: 'center' });
    }
    for (const kind of ['character', 'monster', 'boss', 'prop'] as const) {
      expect(kindDefaults(kind), kind).toMatchObject({ fit: 'feet', anchor: 'feet' });
    }
  });

  it('stretches UI and slices tilesets without the edge gate', () => {
    expect(kindDefaults('ui')).toMatchObject({ fit: 'stretch', edgeGate: false, register: 'sprite' });
    expect(kindDefaults('tileset')).toMatchObject({ fit: 'tile', edgeGate: false, register: 'tileset' });
    expect(kindDefaults('monster')).toMatchObject({ edgeGate: true, register: 'sprite' });
  });

  it('shares one crop window per direction column, per sheet for effects, per cell for icons', () => {
    expect(kindDefaults('monster').share).toBe('column');
    expect(kindDefaults('character').share).toBe('column');
    expect(kindDefaults('vfx').share).toBe('sheet');
    expect(kindDefaults('icon').share).toBe('cell');
  });
});

describe('#20 fitCells', () => {
  it('centres a VFX strip with one window, so the motion between frames survives', () => {
    // two 8×8 cells; a 2×2 blob moves 4 px to the right
    const source = canvas(16, 8);
    rect(source, 1, 3, 2, 2, RED);
    rect(source, 8 + 5, 3, 2, 2, RED);
    const out = fitCells(source, { columns: 2, rows: 1, frameWidth: 8, frameHeight: 8, anchor: 'center', share: 'sheet' });
    expect([out.width, out.height]).toEqual([16, 8]);
    const first = frameBox(out, 0, 0, 8, 8);
    const second = frameBox(out, 1, 0, 8, 8);
    expect(first).not.toBeNull();
    expect(second).not.toBeNull();
    expect(second!.x0).toBeGreaterThan(first!.x1); // still moves right
    expect(Math.abs(first!.x0 - (7 - second!.x1))).toBeLessThanOrEqual(1); // union centred horizontally
    expect(Math.abs(first!.y0 - (7 - first!.y1))).toBeLessThanOrEqual(1); // and vertically
  });

  it('fills each icon cell on its own', () => {
    const source = canvas(16, 8);
    rect(source, 3, 3, 2, 2, BLUE); // small icon
    rect(source, 9, 1, 6, 6, GREEN); // big icon
    const out = fitCells(source, { columns: 2, rows: 1, frameWidth: 8, frameHeight: 8, anchor: 'center', share: 'cell' });
    for (const index of [0, 1]) {
      const box = frameBox(out, index, 0, 8, 8);
      expect(box, `icon ${index}`).not.toBeNull();
      expect(box!.x1 - box!.x0 + 1, `icon ${index} width`).toBeGreaterThanOrEqual(7);
    }
  });

  it('matches fitColumnsToCells for feet + column (existing sheets do not change)', () => {
    const source = canvas(8, 16);
    rect(source, 1, 1, 2, 2, RED);
    rect(source, 3, 13, 2, 2, RED);
    const expected = fitColumnsToCells(source, 1, 2, 4, 4);
    const actual = fitCells(source, { columns: 1, rows: 2, frameWidth: 4, frameHeight: 4, anchor: 'feet', share: 'column' });
    expect(Array.from(actual.data)).toEqual(Array.from(expected.data));
  });
});

describe('#20 tilesets', () => {
  it('slices whole cells edge to edge without cropping', () => {
    const source = canvas(64, 32);
    rect(source, 0, 0, 32, 32, RED);
    rect(source, 32, 0, 32, 32, BLUE);
    rect(source, 32, 0, 16, 16, GREEN); // top-left quarter of the second tile
    const out = sliceTiles(source, 2, 1, 16);
    expect([out.width, out.height]).toEqual([32, 16]);
    for (let i = 3; i < out.data.length; i += 4) expect(out.data[i]).toBe(255);
    expect(pixel(out, 0, 0)).toEqual([200, 0, 0, 255]);
    expect(pixel(out, 15, 15)).toEqual([200, 0, 0, 255]);
    expect(pixel(out, 16, 0)).toEqual([0, 200, 0, 255]); // corner detail stays in its corner
    expect(pixel(out, 31, 15)).toEqual([0, 0, 200, 255]);
  });

  it('writes a .tsx Tiled can load', () => {
    const tsx = buildTsx({
      name: 'ruins',
      image: '../../../art/generated/tilesets/ruins.png',
      tileWidth: 16,
      tileHeight: 16,
      columns: 4,
      tilecount: 12,
      imageWidth: 64,
      imageHeight: 48,
    });
    expect(tsx).toContain('<tileset');
    expect(tsx).toContain('name="ruins"');
    expect(tsx).toContain('tilewidth="16" tileheight="16" tilecount="12" columns="4"');
    expect(tsx).toContain('<image source="../../../art/generated/tilesets/ruins.png" width="64" height="48"/>');
  });
});

describe('#20 UI meta', () => {
  it('writes nine-slice borders into the sprite frame and keeps nearest filtering', () => {
    const meta = spriteFrameMeta('uuid-1', 'panel', 48, 32, { left: 4, right: 5, top: 6, bottom: 7 }) as {
      uuid: string;
      subMetas: Record<string, { userData: Record<string, unknown> }>;
    };
    expect(meta.uuid).toBe('uuid-1');
    expect(meta.subMetas['f9941']?.userData).toMatchObject({
      borderLeft: 4,
      borderRight: 5,
      borderTop: 6,
      borderBottom: 7,
      width: 48,
      height: 32,
    });
    expect(meta.subMetas['6c48a']?.userData).toMatchObject({ minfilter: 'nearest', magfilter: 'nearest' });
  });

  it('has zero borders without nine-slice', () => {
    const meta = spriteFrameMeta('uuid-2', 'icon', 16, 16) as { subMetas: Record<string, { userData: Record<string, unknown> }> };
    expect(meta.subMetas['f9941']?.userData).toMatchObject({ borderLeft: 0, borderRight: 0, borderTop: 0, borderBottom: 0 });
  });
});

describe('#20 attachments', () => {
  it('measures the body bob per frame, per direction column', () => {
    // 2 columns × 3 frames of 4×4; column 0 bobs down one pixel on frame 2
    const sheet = canvas(8, 12);
    rect(sheet, 1, 1, 2, 3, RED);
    rect(sheet, 1, 4 + 2, 2, 2, RED);
    rect(sheet, 1, 8 + 1, 2, 3, RED);
    for (const row of [0, 1, 2]) rect(sheet, 5, row * 4 + 1, 2, 3, BLUE);
    expect(frameBob(sheet, 2, 3, 4, 4)).toEqual([
      [0, 1, 0],
      [0, 0, 0],
    ]);
  });

  const data = validateAttachments({
    version: 1,
    characters: {
      cultivator: {
        frameWidth: 32,
        frameHeight: 32,
        points: {
          back: { down: [16, 12], up: [16, 12], left: [18, 12], right: [14, 12] },
          hand: { down: [20, 20], up: [12, 20], left: [10, 20], right: [22, 20] },
        },
        bob: { idle: { down: [0, 1, 1, 0], up: [0, 1, 1, 0], left: [0, 0, 1, 1], right: [0, 0, 1, 1] } },
      },
    },
    items: {
      'sword-back': {
        sprite: 'attachment.sword-back',
        slot: 'back',
        frameWidth: 16,
        frameHeight: 16,
        grip: { down: [8, 10], up: [8, 10], left: [8, 10], right: [8, 10] },
      },
      staff: {
        sprite: 'attachment.staff',
        slot: 'hand',
        frameWidth: 16,
        frameHeight: 16,
        grip: { down: [8, 12], up: [8, 12], left: [7, 12], right: [9, 12] },
        behind: ['up', 'left'],
      },
    },
  });

  it('places the item grip on the slot point and follows the bob', () => {
    expect(placeAttachment(data, { character: 'cultivator', item: 'sword-back', animation: 'idle', direction: 'down', frame: 1 })).toEqual({
      x: 8,
      y: 3,
      behind: true,
    });
    expect(placeAttachment(data, { character: 'cultivator', item: 'sword-back', animation: 'idle', direction: 'up', frame: 0 })).toEqual({
      x: 8,
      y: 2,
      behind: false,
    });
  });

  it('wraps the frame index and uses no bob for an animation without one', () => {
    const wrapped = placeAttachment(data, { character: 'cultivator', item: 'sword-back', animation: 'idle', direction: 'left', frame: 6 });
    expect(wrapped).toEqual({ x: 10, y: 3, behind: true }); // frame 6 % 4 = 2 → bob 1
    const walk = placeAttachment(data, { character: 'cultivator', item: 'sword-back', animation: 'walk', direction: 'left', frame: 3 });
    expect(walk.y).toBe(2);
  });

  it('draws a hand item behind only when facing up, unless the item overrides it', () => {
    const facing = (direction: 'down' | 'up' | 'left' | 'right'): boolean =>
      placeAttachment(data, { character: 'cultivator', item: 'staff', animation: 'idle', direction, frame: 0 }).behind;
    expect([facing('down'), facing('up'), facing('left'), facing('right')]).toEqual([false, true, true, false]);
    expect(placeAttachment(data, { character: 'cultivator', item: 'staff', animation: 'idle', direction: 'right', frame: 0 })).toMatchObject({
      x: 22 - 9,
      y: 20 - 12,
    });
  });

  it('rejects bad rig data and unknown names', () => {
    expect(() =>
      validateAttachments({ version: 1, characters: {}, items: { bad: { sprite: 'a.b', slot: 'belt', frameWidth: 16, frameHeight: 16, grip: {} } } }),
    ).toThrow(/slot|grip/);
    expect(() => placeAttachment(data, { character: 'nobody', item: 'staff', animation: 'idle', direction: 'down', frame: 0 })).toThrow(
      /nobody/,
    );
    expect(() => placeAttachment(data, { character: 'cultivator', item: 'bow', animation: 'idle', direction: 'down', frame: 0 })).toThrow(/bow/);
  });
});

describe('#20 rooms from text layouts', () => {
  function layout(): string[] {
    const rows: string[][] = [];
    for (let r = 0; r < 18; r += 1) {
      rows.push(Array.from({ length: 32 }, (_, c) => (r === 0 || r === 17 || c === 0 || c === 31 ? '#' : '.')));
    }
    const put = (c: number, r: number, ch: string): void => {
      rows[r]![c] = ch;
    };
    put(16, 9, 'P');
    put(4, 3, 'c');
    put(27, 3, 'k');
    put(10, 8, 'o');
    put(11, 8, 'o');
    put(16, 1, 'D');
    return rows.map((row) => row.join(''));
  }

  const spec: RoomLayoutSpec = {
    chapter: 1,
    room: 7,
    tilesets: [{ source: 'field.tsx', firstgid: 1 }],
    legend: {
      '.': { tile: 37 },
      '#': { tile: 12, obstacle: 'wall' },
      o: { tile: 37, obstacle: 'pillar' },
      P: { tile: 37, playerStart: true },
      c: { tile: 37, spawn: { role: 'chaser', wave: 1 } },
      k: { tile: 37, spawn: { role: 'caster', wave: 2, elite: true } },
      D: { tile: 37, door: { toRoom: 8 } },
    },
    rows: layout(),
  };

  it('writes a .tmx that parseTmxLevel accepts with the objects from the legend', () => {
    const level = parseTmxLevel(buildRoomTmx(spec), { source: 'layout' });
    expect([level.chapter, level.room, level.isBossRoom]).toEqual([1, 7, false]);
    expect(level.playerStart).toEqual({ x: 16.5, y: 9.5 });
    expect(level.waves).toHaveLength(2);
    expect(level.waves[0]?.enemies).toEqual([{ role: 'chaser', at: { x: 4.5, y: 3.5 }, elite: false }]);
    expect(level.waves[1]?.enemies).toEqual([{ role: 'caster', at: { x: 27.5, y: 3.5 }, elite: true }]);
    expect(level.doors).toEqual([{ at: { x: 16.5, y: 1.5 }, toRoom: 8 }]);
    expect(level.obstacles).toContainEqual({ kind: 'pillar', x: 10, y: 8, width: 2, height: 1 });
  });

  it('covers exactly the obstacle cells, with no overlap', () => {
    const level = parseTmxLevel(buildRoomTmx(spec));
    const covered = new Map<string, number>();
    for (const o of level.obstacles.filter((o) => o.kind === 'wall')) {
      for (let y = o.y; y < o.y + o.height; y += 1) for (let x = o.x; x < o.x + o.width; x += 1) {
        covered.set(`${x},${y}`, (covered.get(`${x},${y}`) ?? 0) + 1);
      }
    }
    const walls = new Set<string>();
    spec.rows.forEach((row, y) => [...row].forEach((ch, x) => (ch === '#' ? walls.add(`${x},${y}`) : undefined)));
    expect(new Set(covered.keys())).toEqual(walls);
    expect(Math.max(...covered.values())).toBe(1);
    expect(level.obstacles.length).toBeLessThan(walls.size); // runs are merged, not one rect per cell
  });

  it('writes the legend gids into a 32×18 CSV floor layer', () => {
    const xml = buildRoomTmx(spec);
    expect(xml).toContain('<tileset firstgid="1" source="field.tsx"/>');
    const csv = /<layer[^>]*name="floor"[^>]*>\s*<data encoding="csv">([\s\S]*?)<\/data>/.exec(xml)?.[1] ?? '';
    const values = csv.split(',').map((v) => Number(v.trim())).filter((v) => !Number.isNaN(v));
    expect(values).toHaveLength(32 * 18);
    expect(values[0]).toBe(12);
    expect(values[9 * 32 + 16]).toBe(37);
  });

  it('rejects a wrong size and an unknown character, naming the problem', () => {
    expect(() => buildRoomTmx({ ...spec, rows: spec.rows.slice(1) })).toThrow(/18/);
    const rows = [...spec.rows];
    rows[5] = `#${'?'.repeat(30)}#`;
    expect(() => buildRoomTmx({ ...spec, rows })).toThrow(/\?/);
  });
});
